def get_foods_by_meal_type(meal_type: str) -> list:
    return [f for f in NEPALI_FOOD_DB if meal_type in f["meal_types"]]

def get_food_by_name(name: str):
    name_lower = name.lower()
    for f in NEPALI_FOOD_DB:
        if f["name"].lower() == name_lower or name_lower in [t.lower() for t in f["tags"]]:
            return f
    return None

def get_all_tags_index() -> dict:
    index = {}
    for food in NEPALI_FOOD_DB:
        for tag in food["tags"] + [food["name"].lower()]:
            index[tag.lower()] = food
    return index
